import{_ as t,C as s,o as i,c as r,a5 as n,E as d,j as a,a as c}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Leia e inspecione o feed da LIVE","description":"","frontmatter":{"title":"Leia e inspecione o feed da LIVE","docId":"user.live.feed","translationKey":"user.live.feed","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"695064c8829cdb35f26e51b5ea42e6c108544b66dc0fa07d3bceb05fc98130f3","order":20},"headers":[],"relativePath":"pt/user/live/feed.md","filePath":"pt/user/live/feed.md","lastUpdated":1794611623000}'),l={name:"pt/user/live/feed.md"};function p(u,e,m,v,f,h){const o=s("DemoFrame");return i(),r("div",null,[e[0]||(e[0]=n('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">Leia e inspecione o feed da LIVE <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;Leia e inspecione o feed da LIVE {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Encontre um evento, inspecione seus campos e diferencie uma exibição pausada de uma sala desconectada. Comece com uma <a href="./connections.html">conexão com LIVE</a> ou use eventos já presentes no feed atual. O feed é uma visualização de trabalho limitada, não uma gravação completa de uma transmissão.</p><h2 id="inspect-activity" tabindex="-1">Inspecione a atividade <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;Inspecione a atividade {#inspect-activity}&quot;">​</a></h2><ol><li>Abra <strong>Live feed</strong> e confirme o criador ativo no status da conexão.</li><li>Escolha um filtro de eventos: todos, chat, presentes, curtidas, novos seguidores, entradas ou outras atividades sociais. Combine com pesquisa para encontrar um autor, mensagem, nome de presente ou ID exato de presente.</li><li>Selecione <strong>Pause</strong> para parar a rolagem automática enquanto lê. Os eventos podem continuar chegando e a contagem de não lidos pode aumentar. Esse controle não desconecta o TikTok nem suspende automações.</li><li>Selecione um evento para abrir seu inspetor. Leia o tipo de evento e os detalhes disponíveis antes de escolher campos de automação. Nem todo evento contém texto de chat, informações de presente ou identidade de espectador.</li><li>Selecione o nome ou avatar de um espectador para inspecionar seu perfil acompanhado. Use o controle do inspetor se o painel de detalhes estiver oculto.</li><li>Selecione <strong>Resume</strong> ou o botão de salto para eventos não lidos para voltar à atividade recebida. Limpe a pesquisa e selecione todos os eventos ao verificar se há atividade chegando.</li></ol><p>Use os controles rotulados com foco de teclado quando possível. Pausar a rolagem ajuda quando o movimento dificulta a leitura. Um avatar ausente tem iniciais como alternativa; uma imagem não é necessária para identificar um espectador.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Filtragem e inspeção estão disponíveis. Durante tráfego intenso, a interface pode mostrar uma janela de renderização limitada e informar eventos descartados na interface. Esses indicadores descrevem a exibição; não use a quantidade de linhas visíveis como total contábil. <a href="./../points/statistics.html">Analytics</a> consulta agregados persistidos separadamente.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Se o feed estiver vazio, remova os filtros, retome a rolagem e confira o status da conexão. Uma sala silenciosa pode estar funcionando normalmente. Reconectar ao mesmo criador mantém o contexto; trocar de criador o altera. <strong>Clear</strong> esvazia o feed de trabalho e não redefine pontos nem análises. Investigue indicadores de perda pelos <a href="./../preferences/troubleshooting.html">diagnósticos</a>, sem presumir que todas as linhas ausentes da exibição sejam eventos perdidos na origem.</p>',10)),d(o,{scenario:"feed",locale:"pt",title:"Demonstração: feed"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[c("Detalhes de operação "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalhes de operação {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Esta versão mantém até 300 eventos visíveis e prepara até 900 enquanto a apresentação aguarda. Remove primeiro a linha mais antiga que não é presente; presentes só saem quando não restam outros tipos. Um presente antigo pode permanecer depois de um chat recente. Pausar a rolagem não interrompe a entrada nem garante retenção. Filtros não recuperam linhas removidas; um aviso de perda indica uma visualização incompleta, não autorização para repetir pontos ou ações.",-1))])}const q=t(l,[["render",p]]);export{g as __pageData,q as default};
